tools.example:
model.component("comp1").physics("rad").prop("RadiationSettings").set("radiationMethod", "rayshooting");
model.component("comp1").physics("rad").prop("RadiationSettings").set("radiationResolutionRayShooting", 256);
// Application Library: Heat_Transfer_Module/Thermal_Radiation/parallel_plates_diffuse_specular_ray_shooting

model.component("comp1").physics("rad").create("opac1", "Opacity", 3);
model.component("comp1").physics("rad").feature("opac1").selection().set(2, 3);
// Application Library: Heat_Transfer_Module/Tutorials,_Forced_and_Natural_Convection/heat_sink_surface_radiation; chip_cooling

model.component("comp1").physics("rad").prop("RadiationSettings").set("radiationMethod", "rayshooting");
model.component("comp1").physics("rad").create("osurf1", "OpaqueSurfaceSpecularDiffuse", 1);
// Application Library: Heat_Transfer_Module/Thermal_Radiation/parallel_plates_diffuse_specular_ray_shooting

model.component("comp1").physics("rad").create("ers1", "ExternalRadiationSource", -1);
model.component("comp1").physics("rad").feature("ers1").set("sourcePosition", "SolarPosition");
model.component("comp1").physics("rad").feature("ers1").set("locationType", "City");
// Application Library: Heat_Transfer_Module/Thermal_Radiation/parasol

model.component("comp1").physics("rad").create("rsym1", "SymmetryForSurfaceToSurfaceRadiation", -1);
model.component("comp1").physics("rad").feature("rsym1").set("typeOfSymmetry", "ThreePerpendicularSymmetryPlanes");
// Application Library: Heat_Transfer_Module/Verification_Examples/view_factor; Thermal_Radiation/thermal_annealing, tpv_cell

Results > Surface Integration on the heater boundaries: expression rad.rflux -> net radiated power
Results > Surface plot: rad.J on all diffuse surfaces
// Application Library: Heat_Transfer_Module/Verification_Examples/view_factor

model.component("comp1").physics().create("rpm", "ParticipatingMediaRadiation", "geom1");
model.component("comp1").physics("rpm").feature("rpm1").set("kappaR_mat", "userdef");
model.component("comp1").physics("rpm").feature("rpm1").set("kappaR", "1[1/m]");
// Application Library: Heat_Transfer_Module/Verification_Examples/cylinder_participating_media

model.component("comp1").physics("rpm").create("os2", "OpaqueSurface", 2);
model.component("comp1").physics("rpm").feature("os2").set("epsilon_rad_mat", "userdef");
model.component("comp1").physics("rpm").feature("os2").set("epsilon_rad", "0.8");
// Application Library: Heat_Transfer_Module/Thermal_Radiation/boiler

model.component("comp1").physics("otl").feature("op1").set("orbitType", "circular");
model.component("comp1").physics("otl").feature("op1").set("R_orbit", "otl.R_planet+400[km]");
model.component("comp1").physics("otl").feature("op1").set("i_orbit", "50[deg]");
model.component("comp1").physics("otl").feature("op1").set("omegaType", "ltan");
model.component("comp1").physics("otl").feature("op1").set("omegaTime_orbit", "15[h]");
// Application Library: Heat_Transfer_Module/Orbital_Thermal_Loads/spacecraft_thermal_analysis

model.component("comp1").physics("otl").feature("plp1").set("longType", "spacecraft");
model.component("comp1").physics("otl").feature("plp1").set("planetAlbedoTypeSolAmb", "userdefDistribution");
model.component("comp1").physics("otl").feature("plp1").set("planetAlbedoSolAmb", 0.3);

model.component("comp1").physics("otl").feature("so1").set("primaryRotation", "rate");
model.component("comp1").physics("otl").feature("so1").set("primaryAngularRate", "2*360[deg]/otl.T_orbit");
// Application Library: Heat_Transfer_Module/Orbital_Thermal_Loads/spacecraft_thermal_analysis

model.component("comp2").physics("lts").create("R1", "ConductiveThermalResistor", -1);
model.component("comp2").physics("lts").feature("R1").set("resistorType", "GeometricProperties");
model.component("comp2").physics("lts").feature("R1").set("geomConfig", "PlaneShell");
model.component("comp2").physics("lts").feature("R1").set("A", "pi*(2[cm])^2");
model.component("comp2").physics("lts").feature("R1").set("L", "d_ceram1");
// Application Library: Heat_Transfer_Module/Tutorials,_Thin_Structure/lumped_composite_thermal_barrier

model.component("comp2").physics("lts").create("term1", "ExternalTerminal", -1);
// FEM side: ht > Lumped System Connector (Source = term1)
// Application Library: Heat_Transfer_Module/Tutorials,_Thin_Structure/lumped_composite_thermal_barrier_shells

model.component("comp1").physics().create("mt", "MoistureTransportInAir", "geom1");
model.component("comp1").physics("mt").prop("PhysicalModelProperty").set("MixtureType", "ConcentratedSpecies");
// Results: mt.phi (relative humidity), mt.cv, mt.wc; balance mt.massBalance
// Application Library: Heat_Transfer_Module/Phase_Change/evaporative_cooling

model.component("comp1").physics("mt").create("hporous1", "HygroscopicPorousMediumModel", 2);
// Results: mt.sl (liquid saturation), mt.wc, mt.dwcInt
// Application Library: Heat_Transfer_Module/Phase_Change/potato_drying

model.component("comp1").physics("mt").create("mf1", "MoistureFlux", 1);
// exterior face of a wall with convective moisture flux to ambient air (ampr1.phi_amb)
// Application Library: Heat_Transfer_Module/Buildings_and_Constructions/wood_frame_wall

model.component("comp1").physics("mt").create("tmb1", "ThinMoistureBarrier", 1);
// vapor retarder between insulation and gypsum board
// Application Library: Heat_Transfer_Module/Buildings_and_Constructions/wood_frame_wall

